export const config={id:'rain-study',title:'檐下听雨',subtitle:'A room between weather and warmth',description:'雨线在檐外落下，涟漪沿石阶展开。一幅以代码绘制的雨夜小景。',category:'coding-motion',useCase:'氛围场景 · 品牌开场 · 循环背景',accent:'#dfad70',duration:12,parameter:{label:'雨量',min:10,max:100,step:1,value:64,unit:'%'}};
const mod=(x,n)=>((x%n)+n)%n;
export function rainAmbience(t){const phase=mod(t,12)*Math.PI/6;return{steam:Math.sin(phase),reflections:Array.from({length:15},(_,i)=>Math.sin(i*4+phase))};}
export function rainState(t,value){return Array.from({length:Math.round(Math.max(10,Math.min(100,value))*2)},(_,i)=>{const p=mod(mod(t,12)/1.5+i*.61803398875,1),x=20+mod(i*137.91,1160),ground=572+mod(i*31.7,125);return{x,y:130+Math.min(p/.72,1)*(ground-130),ground,radius:p>.72?(p-.72)/.28*31:0,alpha:p>.72?1-(p-.72)/.28:0,p};});}
export function render(c,{t,value,width,height}){c.save();c.scale(width/1200,height/800);const ambience=rainAmbience(t);let g=c.createLinearGradient(0,0,0,800);g.addColorStop(0,'#12292c');g.addColorStop(1,'#334548');c.fillStyle=g;c.fillRect(0,0,1200,800);
// Distant trees and softly layered silhouettes.
for(let i=0;i<20;i++){c.fillStyle=i%2?'#1b3435':'#203b3a';c.beginPath();c.moveTo(i*76-30,580);c.lineTo(i*76+25,190+(i%5)*39);c.lineTo(i*76+100,580);c.fill();}
c.fillStyle='#263536';c.fillRect(0,570,1200,230);for(let i=0;i<9;i++){c.strokeStyle='#5a68614a';c.beginPath();c.moveTo(0,590+i*22);c.lineTo(1200,590+i*22);c.stroke();}
// Lit dwelling, left of the rain garden.
c.fillStyle='#293330';c.fillRect(64,202,492,375);c.fillStyle='#161f20';c.fillRect(114,235,369,288);g=c.createLinearGradient(140,250,460,500);g.addColorStop(0,'#f6d092');g.addColorStop(.6,'#db9b5c');g.addColorStop(1,'#ad643f');c.fillStyle=g;c.fillRect(135,253,326,246);
c.fillStyle='#6e4934';for(let i=0;i<5;i++)c.fillRect(132+i*81,251,8,250);c.fillRect(132,368,335,9);c.fillStyle='#3b332a';c.fillRect(118,502,362,17);
// Hanging lamp and kettle silhouette.
c.strokeStyle='#5b402c';c.lineWidth=3;c.beginPath();c.moveTo(292,253);c.lineTo(292,304);c.stroke();c.fillStyle='#fff1bb';c.beginPath();c.ellipse(292,312,26,9,0,0,Math.PI*2);c.fill();c.fillStyle='#3c4033';c.beginPath();c.ellipse(386,483,24,19,0,0,Math.PI*2);c.fill();c.fillRect(373,462,25,7);c.beginPath();c.moveTo(402,474);c.lineTo(428,462);c.lineTo(415,485);c.fill();c.strokeStyle='#f8e0aa88';c.lineWidth=2;c.beginPath();c.moveTo(389,452);c.bezierCurveTo(374+ambience.steam*7,433,406,427,390,409);c.stroke();
// Heavy eaves establish shelter.
c.fillStyle='#182525';c.beginPath();c.moveTo(22,221);c.lineTo(131,142);c.lineTo(492,142);c.lineTo(603,221);c.closePath();c.fill();c.strokeStyle='#56706a';c.lineWidth=2;for(let i=0;i<15;i++){c.beginPath();c.moveTo(131+i*25,146);c.lineTo(28+i*40,216);c.stroke();}c.fillStyle='#101d1e';c.fillRect(21,216,583,18);
// Reflections are intentionally painterly, not a water simulation.
for(let i=0;i<15;i++){c.fillStyle=`rgba(224,163,85,${.11*(1-i/16)})`;c.fillRect(134+ambience.reflections[i]*15,580+i*7,330-i*13,3);}
for(const d of rainState(t,value)){if(d.x<580&&d.y<560)continue;if(d.radius){c.strokeStyle=`rgba(176,207,196,${d.alpha*.44})`;c.lineWidth=1;c.beginPath();c.ellipse(d.x,d.ground,d.radius,d.radius*.22,0,0,Math.PI*2);c.stroke();}else{c.strokeStyle=`rgba(191,219,209,${.13+(d.x%4)*.05})`;c.lineWidth=1;c.beginPath();c.moveTo(d.x,d.y);c.lineTo(d.x-4,d.y+17);c.stroke();}}
c.fillStyle='#d9e0d2';c.font='14px "Noto Sans CJK SC", sans-serif';c.fillText('WEATHER STUDIES  /  01',64,66);c.font='56px "Noto Sans CJK SC", serif';c.fillText('檐下听雨',697,283);c.font='17px "Noto Sans CJK SC", sans-serif';c.fillStyle='#a3bcb1';c.fillText('LET THE WORLD SLOW DOWN.',700,322);c.fillStyle='#c7cbb9';c.font='14px "Noto Sans CJK SC", sans-serif';c.fillText('一盏灯，把雨夜分成内外。',700,361);c.strokeStyle='#a4b4a55a';c.beginPath();c.moveTo(700,391);c.lineTo(1100,391);c.stroke();c.fillStyle='#9fafa5';c.font='12px monospace';c.fillText('PROCEDURAL RAIN  /  NO AUDIO',64,751);c.fillText('ORIGINAL CANVAS SCENE',906,751);c.restore();}
